WITH gaps AS (SELECT *, CASE WHEN event_time - LAG(event_time) OVER (PARTITION BY event_type ORDER BY event_time, id) > INTERVAL '90' DAY THEN 1 ELSE 0 END AS is_new_session FROM web_events), islands AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY event_type ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM gaps), deduped AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY event_type ORDER BY is_new_session, id) AS rank_in_group FROM islands QUALIFY rank_in_group = 1), valid AS (SELECT *, FLOOR(rank_in_group) AS rank_in_group_whole, COALESCE(page, 'OTHER') AS page_filled FROM deduped WHERE event_time >= TIMESTAMP '2023-04-06 19:00:00') SELECT *, AVG(burst_id) OVER (PARTITION BY event_type ORDER BY rank_in_group_whole, id ROWS BETWEEN 3 PRECEDING AND 1 PRECEDING) AS burst_id_avg_3_prior, LEAD(is_new_session, 1) OVER w_running AS next_is_new_session FROM valid WINDOW w_running AS (PARTITION BY session_id ORDER BY duration_sec, id)
